Given a large number, the task is to check whether the number is divisible by 12 or not.



Examples : 

Input : 12244824607284961224
Output : Yes

Input : 92387493287593874594898678979792
Output : No

Method 1: This is a very simple approach. if a number is divisible by 4 and 3 then the number is divisible by 12. 



Point 1. If the last two digits of the number are divisible by 4 then the number is divisible by 4. Please see divisibility by 4 for large numbers for details. Point 2. if the sum of all digits of a number is divided by 3 then the number is divisible by 3. Please see divisibility by 3 for large numbers for details. 



            C++

    // C++ Program to check if
// number is divisible by 12
#include <iostream>
using namespace std;

bool isDvisibleBy12(string num)
{
    // if number greater than 3
    if (num.length() >= 3) { 

        // find last digit
        int d1 = (int)num[num.length() - 1];

        // no is odd
        if (d1 % 2 != 0)
            return (0);

        // find second last digit
        int d2 = (int)num[num.length() - 2];

        // find sum of all digits
        int sum = 0;
        for (int i = 0; i < num.length(); i++)
            sum += num[i];            

        return (sum % 3 == 0 && (d2 * 10 + d1) % 4 == 0);            
    }

    else {

        // if number is less than
        // or equal to 100
        int number = stoi(num);
        return (number % 12 == 0);
    }
}

// Driver function
int main()
{
    string num = "12244824607284961224";  
    if (isDvisibleBy12(num))
        cout << "Yes" << endl;
    else
        cout << "No" << endl;
    return 0;
}


